"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { X } from "react-feather";
import { Button, Flex, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useEarnContext } from "../ContextProvider";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const ReviewCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%"
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const InfoRowLabel = styled(Text, {
  color: "$neutral2",
  variant: "body3"
});
const InfoRowValue = styled(Text, {
  color: "$neutral1",
  variant: "body3"
});
const SubmitButton = styled(Button, {
  width: "100%",
  marginTop: "$spacing24",
  py: "$spacing24"
});
const DisclaimerText = styled(Text, {
  variant: "body4",
  color: "$neutral2",
  marginTop: "$spacing24",
  lineHeight: "20px"
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$roundedFull",
  justifyContent: "center",
  alignItems: "center"
});
const Divider = styled(Flex, {
  height: 1,
  backgroundColor: "$surface3",
  width: "100%",
  marginVertical: "$spacing16"
});
export default function ReviewModal({ isOpen, onClose, vault }) {
  const colors = useSporeColors();
  const { transactionAmount: amount, transactionType: type, setTransactionStep } = useEarnContext();
  const tokenSymbol = vault.token.symbol;
  const isDeposit = type === "deposit";
  const title = "Review";
  const actionLabel = isDeposit ? "Deposit" : "Withdraw";
  const parsedAmount = parseFloat(amount || "0");
  const usdValue = parsedAmount;
  const currentPosition = 0;
  const newPosition = isDeposit ? currentPosition + parsedAmount : Math.max(0, currentPosition - parsedAmount);
  const stats = [
    {
      label: `${actionLabel} (${tokenSymbol})`,
      value: <Flex flexDirection="row" alignItems="center" gap="$gap4">
          <InfoRowLabel>{currentPosition < 0.01 ? "< 0.01" : currentPosition.toFixed(2)} →</InfoRowLabel>
          <InfoRowValue>{newPosition.toFixed(2)}</InfoRowValue>
        </Flex>
    },
    {
      label: "APY",
      value: <Flex flexDirection="row" gap="$gap4">
          <InfoRowValue>{vault.apy.toFixed(2)}%</InfoRowValue>
          <Text variant="body2" color="$accent1">
            ✦
          </Text>
        </Flex>
    },
    {
      label: "Exposure",
      value: <Flex flexDirection="row" gap="-8px">
          <PortfolioLogo chainId={UniverseChainId.Mainnet} tokenSymbol="WBTC" tokenName="WBTC" images={[]} size={20} />
          <PortfolioLogo chainId={UniverseChainId.Mainnet} tokenSymbol="WETH" tokenName="WETH" images={[]} size={20} />
          <PortfolioLogo chainId={UniverseChainId.Mainnet} tokenSymbol="USDC" tokenName="USDC" images={[]} size={20} />
        </Flex>
    }
  ];
  return <Modal
    name={"ReviewModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" $md={{ variant: "heading3" }} color="$neutral1">
          {title}
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      <ReviewCard>
        {
    /* Vault Header inside Card */
  }
        <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing24">
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name || ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
          <Text variant="heading3" color="$neutral1">
            {vault.name}
          </Text>
        </Flex>

        {
    /* Amount Section */
  }
        <Text variant="body2" color="$neutral2" mb="$spacing8">
          {actionLabel}
        </Text>

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <Flex flexDirection="row" alignItems="baseline" gap="$gap8">
              <Text variant="heading3" color="$neutral1">
                {amount || "0"}
              </Text>
              <Text variant="heading3" color="$neutral2">
                {tokenSymbol}
              </Text>
            </Flex>
            <UsdPill>
              <Text variant="body4" color="$neutral2">
                ${usdValue.toFixed(2)}
              </Text>
            </UsdPill>
          </Flex>
          {
    /* Icon on right */
  }
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name || ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
        </Flex>

        <Divider />

        {
    /* Stats Grid */
  }
        {stats.map((stat, index) => <InfoRow key={stat.label} style={index === stats.length - 1 ? { marginBottom: 0 } : {}}>
            <InfoRowLabel>{stat.label}</InfoRowLabel>
            {stat.value}
          </InfoRow>)}
      </ReviewCard>

      <DisclaimerText>
        By confirming this transaction, you agree to the{" "}
        <Text variant="body4" style={{ textDecoration: "underline" }}>
          Terms of Use
        </Text>{" "}
        and the services provisions relating to the Morpho Vault.
      </DisclaimerText>

      <SubmitButton size="large" emphasis="primary" onPress={() => setTransactionStep("confirm")}>
        Confirm
      </SubmitButton>
    </Modal>;
}
