"use strict";
import { useState } from "react";
import { Check, ChevronDown } from "react-feather";
import { Flex, Popover, Text, styled as uiStyled, useSporeColors } from "ui/src";
const DropdownButton = uiStyled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap8",
  backgroundColor: "$surface3",
  p: "$spacing8",
  borderRadius: "$roundedFull",
  cursor: "pointer",
  hoverStyle: {
    opacity: 0.8
  }
});
const DropDownItem = uiStyled(Flex, {
  row: true,
  gap: "$spacing4",
  alignItems: "center",
  justifyContent: "space-between",
  cursor: "pointer",
  width: "100%",
  hoverStyle: { backgroundColor: "$surface2" },
  transition: "all 0.2s ease-in-out",
  py: "$spacing8",
  px: "$spacing6",
  borderRadius: "$rounded8"
});
export default function TimeDropdown() {
  const TABS = ["All time", "3 months", "1 month", "1 week"];
  const colors = useSporeColors();
  const [isOpen, setIsOpen] = useState(false);
  const [timeRange, setTimeRange] = useState("All time");
  return <Popover open={isOpen} onOpenChange={setIsOpen}>
      <Popover.Trigger>
        <DropdownButton>
          <Text variant="buttonLabel4" color="$neutral2">
            {timeRange}
          </Text>
          <ChevronDown size={14} color={colors.neutral2.val} />
        </DropdownButton>
      </Popover.Trigger>
      <Popover.Content
    mt={"$spacing8"}
    width={150}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    backgroundColor={"$surface1"}
    enterStyle={{ scale: 0.95, opacity: 0 }}
    exitStyle={{ scale: 0.95, opacity: 0 }}
    elevate
    p="$spacing4"
    animation={[
      "fast",
      {
        opacity: {
          overshootClamping: true
        }
      }
    ]}
  >
        {TABS.map((range) => <DropDownItem
    key={range}
    onPress={() => {
      setTimeRange(range);
      setIsOpen(false);
    }}
  >
            <Text variant="body3" color="$neutral1">
              {range}
            </Text>
            {timeRange === range && <Check size={16} color={colors.neutral1.val} />}
          </DropDownItem>)}
      </Popover.Content>
    </Popover>;
}
