"use strict";
import { createContext, useContext, useState } from "react";
export const EarnContext = createContext(null);
export const EarnContextProvider = ({ children }) => {
  const [activeTab, setActiveTab] = useState("vaults");
  const [transactionStep, setTransactionStep] = useState("idle");
  const [transactionType, setTransactionType] = useState("deposit");
  const [selectedVault, setSelectedVault] = useState(null);
  const [transactionAmount, setTransactionAmount] = useState("");
  const openTransaction = (vault, type, initialStep = "input", initialAmount = "") => {
    setSelectedVault(vault);
    setTransactionType(type);
    setTransactionStep(initialStep);
    setTransactionAmount(initialAmount);
  };
  const closeTransaction = () => {
    setTransactionStep("idle");
    setTransactionAmount("");
    setSelectedVault(null);
  };
  return <EarnContext.Provider
    value={{
      activeTab,
      setActiveTab,
      transactionStep,
      setTransactionStep,
      transactionType,
      setTransactionType,
      selectedVault,
      setSelectedVault,
      transactionAmount,
      setTransactionAmount,
      openTransaction,
      closeTransaction
    }}
  >
      {children}
    </EarnContext.Provider>;
};
export const useEarnContext = () => {
  const context = useContext(EarnContext);
  if (!context) {
    throw new Error("useEarnContext must be used within a EarnContextProvider");
  }
  return context;
};
